def _record(request, data):
    day_text, sku_text, quantity_text = request.args[:3]
    note = request.args[3].strip(WS) if len(request.args) == 4 else ""
    if not _DIGITS_RE.fullmatch(quantity_text) or not quantity_text.strip("0") or len(quantity_text) > 1000:
        raise _refused("bad quantity %r (want a whole number of one or more)" % quantity_text[:40])
    quantity = int(quantity_text)
    sku = _find_sku(data, sku_text)
    if "\n" in note or "\r" in note:
        raise _refused("a note may not contain a line break")
    try:
        note.encode("utf-8")
    except UnicodeEncodeError:
        raise _refused("the note is not valid text")
    day = parse_date(day_text)
    if request.command == "ship":
        quantity = -quantity
    movement = Movement(day, sku, quantity, note)
    if first_below_zero(data.movements + [movement]) is not None:
        raise _refused(
            "stock of %s would go below zero on %s" % (sku, day.isoformat())
        )
    line = "%s %s %s%s" % (
        day.isoformat(),
        sku,
        _signed(quantity),
        " " + note if note else "",
    )
    _append_lines(data, [line])
    return line + "\n"


